      "name": "MvPolynomial.degree_optionEquivLeft",
      "type": " (R : Type u) {σ : Type u_1} [CommSemiring R] {f : MvPolynomial (Option σ) R} (h : f ≠ 0) : ((MvPolynomial.optionEquivLeft R σ) f).degree = ↑(MvPolynomial.degreeOf none f)",
      "module": "Mathlib.Algebra.MvPolynomial.Equiv"
    },
    {
      "name": "MvPolynomial.degreeOf_eq_natDegree",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (a : σ) (p : MvPolynomial σ R) : MvPolynomial.degreeOf a p = ((MvPolynomial.optionEquivLeft R { b // b ≠ a }) ((MvPolynomial.rename ⇑(Equiv.optionSubtypeNe a).symm) p)).natDegree",
